      if (!tokens.length) return null;
      const uk = [];
      const us = [];
      for (let i = 0; i < tokens.length; i++) {
        const hit = bank[tokens[i]];
        if (!hit) return null;
        uk.push(ipaBare(hit.uk));
        us.push(ipaBare(hit.us));
      }
      return { uk: "/" + uk.join(" ") + "/", us: "/" + us.join(" ") + "/" };
