        document.getElementById("madeGapFb" + index).innerHTML = '<div class="feedback ' + (ok ? "ok" : "bad") + '">' +
          (ok ? "Correct" : "Incorrect. Needed: " + esc(input.dataset.gapAnswer)) + "</div>";
