      let item = openTextId ? list.find((row) => row.id === openTextId) : null;
      if (!item) {
        item = { id: Math.random().toString(36).slice(2, 10), title: title, text: text, analysis: null };
        list.unshift(item);
      }
      if (item.text !== text) item.analysis = null;
      item.title = title;
